// TEMPORARY verification script: compile the new Log Explorer SFCs with the
// project's own @vue/compiler-sfc (catches template / script syntax errors
// without running a full build). Delete after use.
import { readFileSync } from 'node:fs'
import { parse, compileScript, compileTemplate } from '@vue/compiler-sfc'

const files = [
  'src/components/logs/explorer/LogVirtualList.vue',
  'src/components/logs/explorer/LogEntryRow.vue',
  'src/components/logs/explorer/LogDetailPanel.vue',
  'src/components/logs/explorer/LogExplorer.vue',
]

let failed = 0
for (const file of files) {
  const source = readFileSync(file, 'utf8')
  const { descriptor, errors } = parse(source, { filename: file })
  const problems = [...errors]
  try {
    const script = compileScript(descriptor, { id: file })
    if (script.content.includes('v-html')) problems.push(new Error('v-html found in compiled script'))
  } catch (err) {
    problems.push(err)
  }
  const template = compileTemplate({
    source: descriptor.template?.content || '',
    filename: file,
    id: file,
  })
  problems.push(...(template.errors || []))
  if (problems.length) {
    failed += 1
    console.log(`FAIL ${file}`)
    problems.forEach((problem) => console.log('  -', problem.message || problem))
  } else {
    console.log(`OK   ${file}`)
  }
}

// The registry change must resolve to the explorer.
const registry = readFileSync('src/config/appComponentsMap.js', 'utf8')
const ok = registry.includes("'log-viewer': lazy(() => import('../components/logs/explorer/LogExplorer.vue'))")
console.log(`${ok ? 'OK  ' : 'FAIL'} registry log-viewer -> LogExplorer.vue`)

process.exit(failed || !ok ? 1 : 0)

