"""TEMPORARY verification for the Log Explorer SFCs (no node available here).

Checks, for every new component:
  * the single-file-component blocks are present and balanced,
  * the <template> tags are balanced (catches the most common typo),
  * no `v-html` is used anywhere,
and confirms the app registry points the `log-viewer` app at LogExplorer.vue.
"""
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
EXPLORER = os.path.join(ROOT, 'src/components/logs/explorer')

FILES = [
    'LogVirtualList.vue',
    'LogEntryRow.vue',
    'LogDetailPanel.vue',
    'LogExplorer.vue',
]

VOID = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
    'meta', 'param', 'source', 'track', 'wbr',
}

TAG_RE = re.compile(r'<(/?)([A-Za-z][\w-]*)((?:[^>"\']|"[^"]*"|\'[^\']*\')*)>', re.S)
COMMENT_RE = re.compile(r'<!--.*?-->', re.S)

failures = []


def check_template(name, template):
    balance = 0
    stack = []
    ok = True
    for match in TAG_RE.finditer(template):
        closing, tag, rest = match.group(1), match.group(2).lower(), match.group(3)
        if tag in VOID:
            continue
        self_closing = rest.rstrip().endswith('/')
        if closing:
            if not stack:
                failures.append(f'{name}: unexpected </{tag}>')
                ok = False
                continue
            expected = stack.pop()
            if expected != tag:
                failures.append(f'{name}: </{tag}> closes <{expected}>')
                ok = False
        elif self_closing:
            continue
        else:
            stack.append(tag)
            balance += 1
    if stack:
        failures.append(f'{name}: unclosed tags {stack}')
        ok = False
    return ok


def check_interpolation(name, template):
    """Every `{{ … }}` must close before the next `<`."""
    for chunk in re.findall(r'\{\{(.*?)\}\}', template, re.S):
        if '<' in chunk:
            failures.append(f'{name}: interpolation contains a tag: {chunk[:60]!r}')


def check_script(name, script):
    """Rough bracket balance of the script block (strings/comments ignored)."""
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    index = 0
    length = len(script)
    while index < length:
        char = script[index]
        nxt = script[index + 1] if index + 1 < length else ''
        if char == '/' and nxt == '/':
            newline = script.find('\n', index)
            index = length if newline == -1 else newline
            continue
        if char == '/' and nxt == '*':
            end = script.find('*/', index + 2)
            index = length if end == -1 else end + 2
            continue
        if char in '\'"`':
            quote = char
            index += 1
            while index < length:
                if script[index] == '\\':
                    index += 2
                    continue
                if script[index] == quote:
                    break
                index += 1
            index += 1
            continue
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack.pop() != pairs[char]:
                failures.append(f'{name}: unbalanced {char!r} in <script>')
                return
        index += 1
    if stack:
        failures.append(f'{name}: unclosed brackets {stack} in <script>')


for filename in FILES:
    path = os.path.join(EXPLORER, filename)
    with open(path, encoding='utf-8') as handle:
        source = handle.read()

    if 'v-html' in source:
        failures.append(f'{filename}: v-html found')

    templates = re.findall(r'<template>(.*)</template>\s*\n\s*<script', source, re.S)
    if not templates:
        failures.append(f'{filename}: no <template> block found')
        continue
    template = COMMENT_RE.sub('', templates[0])
    check_template(filename, template)
    check_interpolation(filename, template)

    scripts = re.findall(r'<script>(.*?)</script>', source, re.S)
    if not scripts:
        failures.append(f'{filename}: no <script> block found')
        continue
    for script in scripts:
        check_script(filename, script)
    print(f'checked {filename}')

with open(os.path.join(ROOT, 'src/config/appComponentsMap.js'), encoding='utf-8') as handle:
    registry = handle.read()
expected = "'log-viewer': lazy(() => import('../components/logs/explorer/LogExplorer.vue'))"
if expected not in registry:
    failures.append('registry: log-viewer does not point to LogExplorer.vue')

for dirpath, _dirnames, filenames in os.walk(EXPLORER):
    for filename in filenames:
        if filename.endswith('.vue'):
            with open(os.path.join(dirpath, filename), encoding='utf-8') as handle:
                if 'v-html' in handle.read():
                    failures.append(f'{filename}: v-html found in the explorer folder')

if failures:
    print('\nFAILURES')
    for failure in failures:
        print(' -', failure)
    sys.exit(1)

print('\nAll structural checks passed (no v-html, templates balanced, registry wired).')

