    return {
      /** Loaded pages of entries (the virtual list renders this array). */
      listEntries: [],
      selectedIndex: -1,
      detailOpen: false,
      detailEntry: null,
      detailRaw: '',
      detailLoading: false,
      contextEntries: [],
      contextLoading: false,
      /** Entries merged by the live tail and not yet acknowledged by the user. */
